cat > and_condition.yara << 'EOF'
rule AndCondition {
  strings:
    $s1 = "mal"
    $s2 = { 90 90 }
  condition:
    $s1 and $s2
}
EOF

cat > sha1_rule.yara << 'EOF'
rule SHA1Match {
  condition:
    hash.sha1(0, filesize) == "aaf4c61ddcc5e8a2dabede0f3b482cd9aea9434d"
}
EOF

cat > foreach.yara << 'EOF'
import "pe"
rule ForEachSection {
  condition:
    for any section in pe.sections : ( section.raw_size > 1000000 )
}
EOF
